def solve_an(N):
    a = {1: 0}
    for n in range(2, N + 1):
        max_val = -1
        for i in range(1, n):
            # Ensure i and n-i are in a
            if i not in a or n - i not in a:
                continue

            val = a[i] + a[n - i] + min(i, n - i)
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a

# Calculate up to n=7 to check the trend
a_values = solve_an(7)
print("a_values up to 7:", a_values)

